INSERT INTO public.prova (id, faculdade_id, nome, periodo, ano, semestre, tipo, qtd_questoes) VALUES ('bbbbbbbb-0001-0000-0000-000000000001', 'aaaaaaaa-0001-0000-0000-000000000001', 'Afya SOI I N1 2025.2', 1, 2025, 2, 'nacional', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('3a9f547c-4a13-4d11-8745-8925bc0bb2fd','bbbbbbbb-0001-0000-0000-000000000001',1,'*(FIP Guanambi)* Um neonato a termo, nascido de parto vaginal, apresenta cianose central e desconforto respiratório poucas horas após o nascimento. A equipe médica suspeita de uma falha na transição da circulação fetal para a neonatal. A ecocardiografia revela que uma estrutura que deveria desviar o sangue da circulação pulmonar na vida fetal permaneceu aberta, permitindo a passagem de sangue da aorta para a artéria pulmonar (shunt esquerda-direita) devido à queda da resistência vascular pulmonar. Essa condição está sobrecarregando a circulação pulmonar do bebê.','Com base no cenário clínico descrito, qual estrutura fetal falhou em seu processo de fechamento fisiológico, resultando na sintomatologia do recém-nascido?','multipla_escolha','O forame oval é uma comunicação entre os átrios, importante na vida fetal para desviar o sangue da direita para a esquerda, evitando o pulmão. Se permanecer aberto, gera shunt atrial — mas o enunciado descreve passagem da aorta para a artéria pulmonar, incompatível com forame oval. O ducto venoso conecta a veia umbilical à veia cava inferior; sua persistência não causa cianose pulmonar. O ducto arterioso conecta a artéria pulmonar à aorta na vida fetal. Após o nascimento, com queda da resistência vascular pulmonar, o fluxo se inverte (aorta → artéria pulmonar), resultando em shunt esquerda-direita e hiperfluxo pulmonar. **Alternativa correta: D.**','MOORE, Keith M.; PERSAUDE, T. V. N. Embriologia Clínica. 11. ed. Rio de Janeiro: GEN Guanabara Koogan, 2020.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('c81729ad-1f2c-472a-ba99-cbebc43b3f4c','3a9f547c-4a13-4d11-8745-8925bc0bb2fd','A','O forame oval, causando um shunt atrial progressivo.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('c2893671-b944-43ee-84c6-81042fe14998','3a9f547c-4a13-4d11-8745-8925bc0bb2fd','B','O ducto venoso, mantendo um desvio do fluxo portal.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('1bb8ec33-b260-4d7d-85d2-deaa516d2704','3a9f547c-4a13-4d11-8745-8925bc0bb2fd','C','As artérias umbilicais, causando fluxo sanguíneo anormal.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('edf11b18-3274-45d2-8a47-09f880ea4c8a','3a9f547c-4a13-4d11-8745-8925bc0bb2fd','D','O ducto arterioso, resultando em hiperfluxo pulmonar.',true,4);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('bab42863-71bb-4355-bf36-4765f5cfa042','bbbbbbbb-0001-0000-0000-000000000001',2,NULL,'*(UNIFIPMOC)* Um homem de 62 anos apresenta dor torácica em aperto após caminhar por alguns minutos. Durante a investigação, o exame de angiotomografia evidencia obstrução significativa em ramo da artéria coronária direita. O médico explica que alterações na irrigação cardíaca comprometem a oferta de oxigênio ao miocárdio, podendo desencadear arritmias. A análise do caso permite concluir que:','multipla_escolha','A perfusão coronária ocorre principalmente na **diástole**, não na sístole — o relaxamento ventricular reduz a compressão dos vasos intramiocárdicos. A circulação coronária é fundamental pois a parede espessa do coração não recebe oxigênio de forma eficaz do sangue intracavitário. O parassimpático **reduz** a frequência cardíaca; quem aumenta é o simpático. O seio coronário faz parte da circulação coronariana, não sistêmica. **Alternativa correta: D.**','TORTORA, Gerard J. Princípios de anatomia e fisiologia. 14ª ed. Rio de Janeiro: Guanabara Koogan, 2019.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('e6aa9fe6-7e9b-4d4e-83d6-80c76db1cdec','bab42863-71bb-4355-bf36-4765f5cfa042','A','A estimulação parassimpática cardíaca aumenta a frequência e a força de contração, elevando a demanda de oxigênio do miocárdio.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('07ed6e59-8926-4674-9dac-f20ee3b64c7c','bab42863-71bb-4355-bf36-4765f5cfa042','B','A perfusão coronária ocorre de forma mais intensa durante a sístole, quando há maior pressão intraventricular.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('07a6978d-7aa4-4d32-b5bc-2a6b0a725e5f','bab42863-71bb-4355-bf36-4765f5cfa042','C','A circulação sistêmica é responsável pelo retorno venoso ao coração por meio do seio coronário.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('69c50b5f-23e4-49a7-b633-da5b0ac03bcf','bab42863-71bb-4355-bf36-4765f5cfa042','D','A circulação coronária garante o suprimento energético ao miocárdio, uma vez que o sangue intracavitário não nutre diretamente a parede cardíaca.',true,4);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('1f214fd9-daf6-4a56-af9f-f7ac101f4c7d','bbbbbbbb-0001-0000-0000-000000000001',3,'*(AFYA Palmas)* Homem, 45 anos, fadiga crônica, desconforto abdominal e diarreia intermitente há 1 mês. Viajou para área rural com saneamento precário. Hemograma: Eosinófilos **18%** (ref: 1–4%), hemácias 4,2 x 10⁶/µL, hemoglobina 12,5 g/dL.','Com base no hemograma e no quadro clínico, qual alternativa descreve corretamente a função da principal célula envolvida na infecção?','multipla_escolha','A **eosinofilia** (eosinófilos 18%) é o achado-chave, fortemente associada a infecções parasitárias por helmintos. Os eosinófilos combatem parasitas grandes liberando grânulos citotóxicos (proteína básica principal — MBP, e proteína catiônica — ECP) que perfuram a membrana do parasita. Essa é sua função primária — diferente dos neutrófilos (fagocitose de bactérias) e linfócitos B (produção de anticorpos). **Alternativa correta: D.**','ABBAS, A. K. et al. Imunologia Básica. 7. ed. Rio de Janeiro: GEN Guanabara Koogan, 2025.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('b5da6257-67c0-4278-b011-461c1a787d4f','1f214fd9-daf6-4a56-af9f-f7ac101f4c7d','A','Diferencia-se em plasmócitos para produzir anticorpos específicos que neutralizam toxinas e patógenos extracelulares.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('b2833b5a-714c-4ac9-ae98-74e48f0fca90','1f214fd9-daf6-4a56-af9f-f7ac101f4c7d','B','Atua como célula apresentadora de antígenos, ativando outras células de defesa para coordenar a resposta imune adaptativa.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('3d38b21b-7a1f-407c-9203-7386d5c84b08','1f214fd9-daf6-4a56-af9f-f7ac101f4c7d','C','Realiza a fagocitose de pequenas bactérias e fungos, sendo a primeira linha de defesa celular.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('7371fb88-6459-433e-a4da-55afc95564e2','1f214fd9-daf6-4a56-af9f-f7ac101f4c7d','D','Libera grânulos citotóxicos para danificar a membrana e a parede de parasitas grandes que não podem ser fagocitados.',true,4);;
